import argparse
import hashlib
import json
import os
from pathlib import Path
import sys

def fingerprint(path):
    digest = hashlib.sha256()
    with path.open("rb") as handle:
        while True:
            chunk = handle.read(1024 * 1024)
            if not chunk:
                break
            digest.update(chunk)
    return digest.hexdigest()

def report_error(error):
    print(f"Skipped: {error}", file=sys.stderr)

def duplicates(root):
    by_size = {}
    for directory, dirs, files in os.walk(
        root, followlinks=False, onerror=report_error
    ):
        base = Path(directory)
        dirs[:] = sorted(
            name for name in dirs if not (base / name).is_symlink()
        )
        for name in sorted(files):
            path = base / name
            try:
                if path.is_symlink() or not path.is_file():
                    continue
                by_size.setdefault(path.stat().st_size, []).append(path)
            except OSError as error:
                report_error(error)
    matches = []
    for size, paths in sorted(by_size.items()):
        if len(paths) < 2:
            continue
        by_digest = {}
        for path in paths:
            try:
                digest = fingerprint(path)
            except OSError as error:
                report_error(error)
                continue
            by_digest.setdefault(digest, []).append(str(path))
        matches.extend(sorted(group) for group in by_digest.values()
                       if len(group) > 1)
    return sorted(matches)

def main():
    parser = argparse.ArgumentParser(description="Report duplicate candidates")
    parser.add_argument("root", type=Path)
    args = parser.parse_args()
    root = args.root.expanduser()
    if root.is_symlink() or not root.is_dir():
        parser.error("root must be an existing non-symlink directory")
    print(json.dumps(duplicates(root), indent=2, ensure_ascii=False))

if __name__ == "__main__":
    main()
